  cpu_intel_die_package_energy_wrap_range_joules: { label: "Rango cíclico de energía del paquete por die", hint: "Energía en julios tras la cual el contador de energía del paquete de este die vuelve a empezar; es una constante." },
  cpu_intel_die_dram_energy_counter_raw: { label: "Contador de energía DRAM por die (sin procesar)", hint: "Contador RAPL sin procesar de la energía de la DRAM leído en un die, útil solo para calcular la potencia; requiere el modo DRAM RAPL de la BIOS, y un valor cero no demuestra que la medición esté activada." },
  cpu_intel_die_dram_energy_reported_joules: { label: "Energía DRAM por die (cíclico, J)", hint: "Contador de energía de la DRAM de este die convertido a julios con la unidad nominal del modelo; se reinicia al desbordarse, requiere el modo DRAM RAPL de la BIOS, y un valor cero no demuestra que la medición esté activada." },
  cpu_intel_die_dram_energy_unit_joules: { label: "Unidad de energía DRAM por die", hint: "Julios nominales por unidad del contador de energía de la DRAM de este die, específicos del modelo; es una constante de escala." },
  cpu_intel_die_dram_energy_wrap_range_joules: { label: "Rango cíclico de energía DRAM por die", hint: "Energía en julios tras la cual el contador de energía de la DRAM de este die vuelve a empezar; es una constante." },
  cpu_intel_die_package_power_information_raw: { label: "Info. de potencia por die (sin procesar)", hint: "Registro RAPL sin procesar de información de potencia del paquete leído en un die; contiene valores de especificación declarados, no potencia medida." },
  cpu_intel_die_package_thermal_spec_power_declared_watts: { label: "TDP por die (declarado)", hint: "Potencia de especificación térmica que este die declara en RAPL; es un valor declarado, no una potencia medida ni un máximo garantizado." },
  cpu_intel_die_package_minimum_power_setting_declared_watts: { label: "Potencia mínima por die (declarado)", hint: "Ajuste de potencia del paquete más bajo que este die declara en RAPL; es un valor declarado, no una potencia medida ni un máximo garantizado." },
  cpu_intel_die_package_maximum_power_setting_declared_watts: { label: "Potencia máxima por die (declarado)", hint: "Ajuste de potencia del paquete más alto que este die declara en RAPL; es un valor declarado, no una potencia medida ni un máximo de consumo garantizado." },
  cpu_intel_package_power_information_raw: { label: "Info. de potencia del paquete (sin procesar)", hint: "Registro RAPL completo sin procesar de información de potencia del paquete; no es un contador de energía ni una medición de potencia." },
  cpu_intel_package_thermal_spec_power_declared_watts: { label: "TDP del paquete (declarado)", hint: "Potencia de especificación térmica que el paquete de la CPU declara en RAPL; no es una potencia medida, el PL1/PL2 activo ni un máximo garantizado." },
  cpu_intel_package_minimum_power_setting_declared_watts: { label: "Potencia mínima del paquete (declarado)", hint: "Ajuste de potencia más bajo que el paquete de la CPU declara como permitido en RAPL; no es una potencia medida, el PL1/PL2 activo ni un máximo garantizado." },
  cpu_intel_package_maximum_power_setting_declared_watts: { label: "Potencia máxima del paquete (declarado)", hint: "Ajuste de potencia más alto que el paquete de la CPU declara como permitido en RAPL; no es una potencia medida, el PL1/PL2 activo ni un máximo garantizado." },
  cpu_intel_dram_power_information_raw: { label: "Info. de potencia DRAM (sin procesar)", hint: "Registro RAPL completo sin procesar de información de potencia de la DRAM; no es un contador de energía ni una medición de potencia." },
  cpu_intel_dram_thermal_spec_power_declared_watts: { label: "TDP de DRAM (declarado)", hint: "Potencia de especificación térmica declarada para el dominio DRAM en RAPL; no es una potencia medida ni un máximo garantizado." },
  cpu_intel_dram_minimum_power_setting_declared_watts: { label: "Potencia mínima DRAM (declarado)", hint: "Ajuste de potencia más bajo declarado como permitido para el dominio DRAM en RAPL; no es una potencia medida ni un máximo garantizado." },
  cpu_intel_dram_maximum_power_setting_declared_watts: { label: "Potencia máxima DRAM (declarado)", hint: "Ajuste de potencia más alto declarado como permitido para el dominio DRAM en RAPL; no es una potencia medida ni un máximo garantizado." },
  cpu_intel_aperf_mperf_interval_ratio: { label: "Relación de rendimiento (APERF/MPERF)", hint: "Variación de APERF dividida entre la variación de MPERF de este procesador lógico durante el último intervalo, que compara el reloj real y el de referencia mientras se ejecuta; no es una frecuencia en MHz ni el uso de la CPU." },
  cpu_intel_aperf_counter_raw: { label: "Contador APERF (sin procesar)", hint: "Contador de realimentación APERF de 64 bits sin procesar de este procesador lógico; solo tiene sentido como parte de la relación APERF/MPERF, no como recuento de ciclos ni lectura de frecuencia." },
  cpu_intel_mperf_counter_raw: { label: "Contador MPERF (sin procesar)", hint: "Contador de realimentación MPERF de 64 bits sin procesar de este procesador lógico; solo cuenta mientras el procesador está en ejecución (C0), puede reiniciarse y no es el tiempo total de ejecución." },
  cpu_intel_package_energy_counter_raw: { label: "Contador de energía del paquete (sin procesar)", hint: "Contador RAPL de 32 bits sin procesar de la energía del paquete, útil solo para calcular la potencia; se reinicia al desbordarse y no es la energía acumulada total." },
  cpu_intel_package_energy_reported_joules: { label: "Energía del paquete (cíclico, J)", hint: "Contador de energía del paquete multiplicado por su unidad, en julios; se reinicia al desbordarse y no es la energía del intervalo ni la potencia calibrada en el enchufe." },
  cpu_intel_package_energy_unit_joules: { label: "Unidad de energía del paquete", hint: "Julios que representa una unidad del contador de energía del paquete; es una constante de escala." },
  cpu_intel_package_energy_wrap_range_joules: { label: "Rango cíclico de energía del paquete", hint: "Energía en julios que abarca una vuelta completa del contador de 32 bits del paquete; es una constante, no el valor máximo del contador." },
  cpu_intel_pp0_energy_counter_raw: { label: "Contador de energía PP0 (sin procesar)", hint: "Contador de energía de 32 bits sin procesar del plano de potencia PP0 (núcleos) del paquete, útil solo para calcular la potencia; no corresponde a un núcleo individual." },
  cpu_intel_pp0_energy_reported_joules: { label: "Energía PP0 (cíclico, J)", hint: "Contador de energía del plano PP0 en julios; se reinicia al desbordarse, se solapa con el dominio del paquete y no debe sumarse a él." },
  cpu_intel_pp0_energy_unit_joules: { label: "Unidad de energía PP0", hint: "Julios que representa una unidad del contador de energía PP0; es una constante de escala." },
  cpu_intel_pp0_energy_wrap_range_joules: { label: "Rango cíclico de energía PP0", hint: "Energía en julios que abarca una vuelta completa del contador PP0 de 32 bits; es una constante." },
  cpu_intel_pp1_energy_counter_raw: { label: "Contador de energía PP1 (sin procesar)", hint: "Contador de energía de 32 bits sin procesar del plano de potencia PP1, útil solo para calcular la potencia; lo que abarca PP1 depende del modelo de CPU y no siempre son los gráficos integrados." },
