  cpu_intel_pp1_energy_unit_joules: { label: "Unidad de energía PP1", hint: "Julios que representa una unidad del contador de energía PP1; es una constante de escala." },
  cpu_intel_pp1_energy_wrap_range_joules: { label: "Rango cíclico de energía PP1", hint: "Energía en julios que abarca una vuelta completa del contador PP1 de 32 bits; es una constante." },
  cpu_intel_dram_energy_counter_raw: { label: "Contador de energía DRAM (sin procesar)", hint: "Contador de energía de la DRAM de 32 bits sin procesar, útil solo para calcular la potencia; una lectura de cero no demuestra que la BIOS tenga activada la medición de energía de la DRAM." },
  cpu_intel_dram_energy_reported_joules: { label: "Energía DRAM (cíclico, J)", hint: "Contador de energía de la DRAM en julios con la unidad documentada del modelo; se reinicia al desbordarse y requiere el modo DRAM RAPL de la plataforma." },
  cpu_intel_dram_energy_unit_joules: { label: "Unidad de energía DRAM", hint: "Julios por unidad del contador de energía de la DRAM, específicos del modelo y posiblemente distintos de la unidad del paquete; es una constante de escala." },
  cpu_intel_dram_energy_wrap_range_joules: { label: "Rango cíclico de energía DRAM", hint: "Energía en julios que abarca una vuelta completa del contador DRAM de 32 bits en su unidad nominal; es una constante." },
  cpu_intel_core_dts_temperature: { label: "Temperatura del núcleo (DTS)", hint: "Temperatura de este núcleo, calculada como el objetivo de temperatura predeterminado menos la lectura del sensor térmico digital (DTS) del núcleo; usa el objetivo predeterminado, no un punto de limitación ajustado con desplazamiento." },
  cpu_intel_package_dts_temperature: { label: "Temperatura del paquete (DTS)", hint: "Temperatura del paquete, calculada como el objetivo de temperatura predeterminado menos la lectura del sensor térmico digital del paquete; no es una media de las temperaturas de los núcleos." },
  cpu_intel_core_dts_distance_to_target_celsius: { label: "Margen del núcleo al objetivo térmico", hint: "Cuántos °C está este núcleo por debajo de su objetivo de temperatura, según su sensor térmico digital; solo se proporciona cuando la lectura está marcada como válida." },
  cpu_intel_package_dts_distance_to_target_celsius: { label: "Margen del paquete al objetivo térmico", hint: "Cuántos °C está el paquete por debajo de su objetivo de temperatura, según el sensor térmico digital del paquete, que no tiene indicador de validez." },
