  memory_all_numa_node_available_bytes: { label: "Memoria disponible del nodo NUMA", hint: "Memoria libre y puesta a cero en este nodo NUMA según Windows; la memoria en espera solo se incluye en sistemas de un único nodo, y no es la capacidad del nodo ni la memoria disponible de todo el sistema." },
  storage_all_ata_smart_data_raw: { label: "Página de datos ATA SMART (sin procesar)", hint: "Página exacta de 512 bytes de atributos ATA SMART; los valores sin procesar del fabricante y los normalizados no se interpretan." },
