  gpu_amd_activity_percent: { label: "Actividad de la GPU (ADLX)", hint: "Muestra de uso de la GPU que informa AMD ADLX; la ventana de muestreo del fabricante no está especificada y, si falta, no se sustituye por otra fuente." },
  gpu_amd_voltage_reported_volts: { label: "Voltaje de la GPU (ADLX)", hint: "Voltaje de la GPU que informa AMD ADLX, convertido de mV a V; no se especifica qué raíl mide, y no es el VID ni un desplazamiento de ajuste." },
