  gpu_amd_npu_frequency_mhz: { label: "Frecuencia de la NPU (ADLX)", hint: "Frecuencia de la NPU que AMD ADLX informa para este dispositivo gráfico, en MHz; es un valor del fabricante no vinculado a un dispositivo NPU concreto." },
